INSERT INTO public.categories (slug, title, meta_title, description, symbol, intro, sort_order, is_active)
VALUES
  ('hanuman', 'हनुमान जी', 'हनुमान जी | भक्ति, प्रेरणा और ज्ञान', 'हनुमान जी की भक्ति, प्रेरणादायक प्रसंग, मंत्र और आध्यात्मिक विचार।', 'श्री राम', 'पवनपुत्र श्री हनुमान जी भक्ति, शक्ति, समर्पण और निस्वार्थ सेवा के सर्वोच्च आदर्श हैं। यहां हनुमान जी की साधना, चालीसा और प्रेरणादायक विचारों का संग्रह प्रस्तुत है।', 1, true),
  ('radha-krishna', 'राधा कृष्ण', 'राधा कृष्ण | प्रेम, लीला और भक्ति', 'राधा-कृष्ण की भक्ति, प्रेम, लीलाओं और आध्यात्मिक संदेशों से जुड़े लेख।', 'राधे', 'श्री राधा-कृष्ण का दिव्य संबंध प्रेम, समर्पण और निष्काम भक्ति का परम स्वरूप है। यहां राधा-कृष्ण भक्ति और उनकी लीलाओं से जुड़े लेख संकलित हैं।', 2, true),
  ('shiv', 'भगवान शिव', 'भगवान शिव | महादेव, मंत्र और साधना', 'महादेव, शिव भक्ति, मंत्र, कथाओं और आध्यात्मिक ज्ञान से जुड़ी सामग्री।', 'ॐ नमः शिवाय', 'देवाधिदेव महादेव सरलता, वैराग्य और परम कल्याण के प्रतीक हैं। यहां भगवान शिव की भक्ति, पंचाक्षर मंत्र और कथाओं से जुड़ी सामग्री उपलब्ध है।', 3, true),
  ('bhagavad-gita', 'श्रीमद्भगवद्गीता', 'श्रीमद्भगवद्गीता | श्लोक, संदेश और जीवन दर्शन', 'गीता के श्लोक, जीवन से जुड़े संदेश और सरल भाषा में आध्यात्मिक ज्ञान।', 'गीता', 'श्रीमद्भगवद्गीता सनातन धर्म का शाश्वत ज्ञानग्रंथ है, जो कर्मयोग, मन के नियंत्रण और आंतरिक शांति के व्यावहारिक सूत्र सिखाता है।', 4, true),
  ('festivals', 'त्योहार एवं व्रत', 'त्योहार एवं व्रत | सनातन पर्व, नियम और महत्व', 'एकादशी, जन्माष्टमी, नवरात्रि, शिवरात्रि और अन्य धार्मिक पर्वों की जानकारी।', 'दीप', 'सनातन परंपरा के व्रत और पर्व आत्मसंयम, भक्ति और आध्यात्मिक उत्सव के पावन अवसर हैं। यहां प्रमुख धार्मिक पर्वों की जानकारी संकलित है।', 5, true),
  ('vrindavan', 'वृंदावन एवं धाम', 'वृंदावन एवं धाम | दर्शन, मंदिर और यात्रा गाइड', 'वृंदावन, मथुरा और प्रमुख धार्मिक स्थलों से जुड़ी यात्रा एवं आध्यात्मिक जानकारी।', 'राधे राधे', 'वृंदावन धाम भक्ति और प्रेम की पावन स्थली है। यहां धाम दर्शन, प्रमुख मंदिरों और आध्यात्मिक यात्रा से जुड़े उपयोगी मार्गदर्शक लेख पढ़ें।', 6, true),
  ('bhakti-vichar', 'भक्ति विचार', 'भक्ति विचार | मन की शांति और सकारात्मक चिंतन', 'मन की शांति, सकारात्मक जीवन और भक्ति से जुड़े छोटे लेकिन सार्थक विचार।', 'शांति', 'व्यस्त जीवन में मन को शांत करने, ईश्वर का स्मरण बनाए रखने और सकारात्मक चिंतन के लिए सरल एवं प्रेरक भक्ति विचार।', 7, true),
  ('premanand-ji', 'प्रेमानंद जी', 'प्रेमानंद जी | विचार, सत्संग और भक्ति मार्ग', 'प्रेमानंद जी महाराज से जुड़े सार्वजनिक रूप से उपलब्ध विचारों, प्रसंगों और भक्ति संबंधी विषयों पर सामग्री।', 'ॐ', 'वृंदावन के श्रद्धेय संत पूज्य प्रेमानंद जी महाराज से जुड़े सार्वजनिक रूप से उपलब्ध सत्संग विचार, नाम-जप का महत्व और भक्ति मार्ग पर मार्गदर्शन।', 8, true)
