-- Article 1/18: sacchi-bhakti-kya-hai
INSERT INTO public.articles (
  slug,
  title,
  description,
  category_id,
  author_id,
  status,
  sections,
  symbol,
  read_time,
  featured,
  published_at
)
VALUES (
  'sacchi-bhakti-kya-hai',
  'सच्ची भक्ति क्या है? दैनिक जीवन में भक्ति का महत्व',
  'जानिए भक्ति का वास्तविक अर्थ, मन की एकाग्रता और इसे अपने दैनिक जीवन का हिस्सा कैसे बनाया जा सकता है।',
  (SELECT id FROM public.categories WHERE slug = 'bhakti-vichar' LIMIT 1),
  (SELECT id FROM public.authors WHERE slug = 'editorial-team' LIMIT 1),
  'published',
  '[{"heading":"भक्ति का वास्तविक और सरल अर्थ","paragraphs":["सनातन संस्कृति में ''भक्ति'' शब्द ''भज्'' धातु से बना है, जिसका अर्थ है—जुड़ना, सेवा करना या ईश्वर के प्रति संपूर्ण प्रेमभाव रखना। सामान्यतः लोग भक्ति को केवल मंदिर जाने, माला फेरने या कुछ निश्चित समय की पूजा तक सीमित मान लेते हैं। लेकिन भक्ति केवल कर्मकांड नहीं, बल्कि एक अंतःकरण की स्थिति है।","सच्ची भक्ति का अर्थ है—अपने मन, वचन और कर्म को उस परम चेतना के प्रति समर्पित कर देना। जब मनुष्य के हृदय में यह भाव जाग्रत होता है कि संसार की प्रत्येक वस्तु और प्राणी उसी एक ईश्वर का अंश है, तब उसके प्रत्येक कार्य में सहज ही पवित्रता और करुणा आ जाती है। यही भक्ति का आरंभ है।"],"highlight":"“भक्ति किसी विशेष स्थान या समय की मोहताज नहीं है; जहां हृदय में प्रेम और सरलता है, वहीं ईश्वर का वास है।”"},{"heading":"पूजा-पाठ और भक्ति में क्या अंतर है?","paragraphs":["कई साधक यह प्रश्न करते हैं कि क्या प्रतिदिन पूजा करना ही भक्ति है? पूजा-पाठ भक्ति का एक महत्वपूर्ण माध्यम अवश्य है। यह हमें अनुशासन, पवित्रता और एकाग्रता सिखाता है। दीपक जलाना, पुष्प अर्पित करना और आरती गाना हमारे मन को शांत करने में सहायक होते हैं।","परंतु यदि पूजा के पश्चात हमारा मन द्वेष, ईर्ष्या, क्रोध या छल-कपट में लगा रहे, तो वह पूजा केवल एक औपचारिकता बनकर रह जाती है। भक्ति उस स्थिति का नाम है जहां पूजा केवल मंदिर के कक्ष तक सीमित न रहकर पूरे जीवन में प्रवाहित होने लगे। जब आपके व्यवहार में दया, वाणी में मिठास और हृदय में संतोष आ जाए, तो समझिए कि भक्ति फलने-फूलने लगी है।"]},{"heading":"दैनिक जीवन में भक्ति को कैसे अपनाएं?","paragraphs":["दैनिक जीवन में भक्ति को उतारने के लिए हमें अपने गृहस्थ जीवन या कार्यों को छोड़ने की आवश्यकता नहीं है। महर्षियों और संतों ने सदैव यही सिखाया है कि संसार में रहते हुए भी कमल के पत्ते की भांति निर्लिप्त रहना ही सच्ची साधना है।","जब आप प्रातःकाल उठें, तो पहला विचार कृतज्ञता का होना चाहिए। इस नए दिन, श्वास और जीवन के लिए ईश्वर को धन्यवाद दें। जब आप भोजन ग्रहण करें, तो उसे प्रभु का प्रसाद समझकर स्वीकार करें। जब आप अपने कार्यस्थल पर जाएं, तो अपने कार्य को ईश्वर की पूजा समझकर ईमानदारी से पूरा करें। यही कर्मयोग और भक्तियोग का सुंदर समन्वय है।"],"bullets":["प्रातः स्मरण: दिन की शुरुआत 2 मिनट मौन बैठकर ईश्वर के प्रति कृतज्ञता से करें।","वाणी का संयम: कटु वचनों से बचें; हर व्यक्ति में ईश्वर का अंश देखकर बात करें।","समर्पण भाव: परिणाम की अत्यधिक चिंता किए बिना श्रेष्ठ कर्म करें और फल ईश्वर पर छोड़ दें।","सेवा कार्य: किसी असहाय, जीव-जंतु या जरूरतमंद की निस्वार्थ सहायता करना भी प्रत्यक्ष भक्ति है।"]},{"heading":"कर्म करते हुए ईश्वर का स्मरण (कर्मयोग)","paragraphs":["श्रीमद्भगवद्गीता में भगवान श्री कृष्ण अर्जुन से कहते हैं—''तस्मात्सर्वेषु कालेषु मामनुस्मर युध्य च''। अर्थात्, हर समय मेरा स्मरण करो और अपना कर्तव्य (युद्ध) भी करो। इसका सीधा अर्थ है कि सांसारिक जिम्मेदारियों से भागना भक्ति नहीं है, बल्कि जिम्मेदारियों को निष्ठापूर्वक निभाते हुए मन को ईश्वर में स्थिर रखना ही वास्तविक भक्ति है।","एक किसान जब खेत में हल चलाता है, एक चिकित्सक जब रोगी की सेवा करता है, एक शिक्षक जब ज्ञान बांटता है, अथवा एक माता जब अपनी संतान का पालन करती है—यदि वे अपने कर्म को प्रभु सेवा मानकर करें, तो उनका हर क्षण साधना बन जाता है।"]},{"heading":"मन की शांति और समर्पण का आनंद","paragraphs":["आज के आधुनिक जीवन में तनाव, अनिद्रा और मानसिक अशांति का सबसे बड़ा कारण है—''अहंकार'' और ''नियंत्रण की इच्छा''। मनुष्य सोचता है कि सब कुछ उसके अनुसार होना चाहिए। जब परिस्थितियां विपरीत होती हैं, तो वह टूट जाता है।","सच्चा भक्त जानता है कि वह केवल एक निमित्त मात्र है, कर्ता तो परमात्मा हैं। इस शरणागति से मन का भारी बोझ उतर जाता है। जब व्यक्ति प्रभु पर पूर्ण विश्वास कर लेता है, तो उसे सुख और दुख दोनों में समभाव रहने की शक्ति मिलती है। यही समत्व भाव मनुष्य को भीतर से अखंड शांति प्रदान करता है।"]},{"heading":"उपसंहार: जीवन को भक्तिमय बनाएं","paragraphs":["संक्षेप में कहें तो सच्ची भक्ति कोई कठिन तपस्या नहीं, बल्कि सरल और सहज जीवन जीने की कला है। यह अपने भीतर प्रेम, विनम्रता और संतोष को जगाने की प्रक्रिया है। जब आप दूसरों के दुख को समझ सकें और अपने सुख में प्रभु का अनुग्रह देख सकें, तब जीवन सचमुच भक्तिमय हो जाता है।","आज से ही संकल्प लें कि दिन का प्रत्येक कर्म ईश्वर को अर्पित करते हुए करेंगे। ऐसा करने से आपका जीवन न केवल स्वयं के लिए शांतिप्रद बनेगा, बल्कि आपके संपर्क में आने वाले हर व्यक्ति को भी सकारात्मक ऊर्जा और प्रेम की अनुभूति होगी।"]}]'::jsonb,
  'दीप',
  '6 मिनट',
  false,
  '2026-03-18T06:00:00+05:30'::timestamptz
)
ON CONFLICT (slug) DO UPDATE SET
