  (SELECT id FROM public.authors WHERE slug = 'editorial-team' LIMIT 1),
  'published',
  '[{"heading":"राधा-कृष्ण प्रेम का आध्यात्मिक रहस्य","paragraphs":["सनातन परंपरा में श्री राधा-कृष्ण का संबंध लौकिक प्रेम से परे, जीवात्मा और परमात्मा के परम मिलन का प्रतीक है। ''राधा'' और ''कृष्ण'' दो अलग सत्ताएं नहीं, बल्कि एक ही पूर्ण ब्रह्म के दो रूप हैं—एक रस है तो दूसरा रस का आस्वादन करने वाला।","राधा जी प्रेम की पराकाष्ठा हैं और श्री कृष्ण उस प्रेम के आधार हैं। जब कोई साधक राधा-कृष्ण की भक्ति में प्रवेश करता है, तो उसका हृदय सांसारिक कामनाओं से ऊपर उठकर दिव्य आनंद की ओर अग्रसर होता है।"],"highlight":"“जहां कोई स्वार्थ नहीं, कोई शर्त नहीं और कोई मांग नहीं—वही राधा-कृष्ण का सच्चा प्रेम है।”"},{"heading":"निस्वार्थ समर्पण और निष्काम भाव","paragraphs":["आज के संसार में प्रेम प्रायः लेन-देन पर आधारित होता है। हम किसी से प्रेम करते हैं तो बदले में सम्मान, अधिकार या अपेक्षा रखते हैं। परंतु श्री राधा रानी का प्रेम सिखाता है कि प्रेम का अर्थ पाना नहीं, बल्कि स्वयं को पूर्णतः समर्पित कर देना है।","राधा जी ने कृष्ण से कभी अपने सुख की मांग नहीं की; कृष्ण का सुख ही उनका सुख था। निष्काम भक्ति का यही सर्वोच्च आदर्श है—प्रभु से कुछ मांगने के बजाय केवल प्रभु के आनंद के लिए जीना।"],"bullets":["अपेक्षा रहित प्रेम: जब आप बिना किसी फल की लालसा के ईश्वर से प्रेम करते हैं, तो भक्ति परिपक्व होती है।","अहंकार का विसर्जन: प्रेम में ''मैं'' और ''मेरा'' मिट जाता है, केवल प्रियतम की प्रसन्नता शेष रह जाती है।","सर्वत्र दर्शन: राधा भाव का अर्थ है हर कण में अपने आराध्य का रूप देखना।"]},{"heading":"दैनिक जीवन में राधा-कृष्ण के आदर्श","paragraphs":["राधा-कृष्ण की भक्ति हमें केवल भावविभोर होना ही नहीं सिखाती, बल्कि हमारे पारिवारिक और सामाजिक संबंधों को भी पवित्र बनाती है। यदि हम अपने दैनिक जीवन में इस निष्काम प्रेम का एक छोटा सा अंश भी उतार लें, तो हमारे घरों से कलह, ईर्ष्या और कटुता समाप्त हो सकती है।","परस्पर सम्मान, त्याग की भावना और एक-दूसरे की कमियों को स्वीकार करते हुए साथ चलना ही राधा-कृष्ण के प्रेम का व्यावहारिक स्वरूप है।"]},{"heading":"निष्कर्ष","paragraphs":["श्री राधा-कृष्ण का स्मरण हमें याद दिलाता है कि जीवन की सार्थकता केवल धन और प्रतिष्ठा अर्जित करने में नहीं, बल्कि हृदय में प्रेम और करुणा को जीवंत रखने में है। जब हम अपने आराध्य को अपना सर्वस्व मान लेते हैं, तो जीवन स्वयं एक सुंदर रास बन जाता है।"]}]'::jsonb,
  'मोरपंख',
  '5 मिनट',
  false,
  '2026-03-17T06:00:00+05:30'::timestamptz
)
