  read_time,
  featured,
  published_at
)
VALUES (
  'hanuman-ji-vishwas-samarpan',
  'हनुमान जी से सीखें विश्वास और समर्पण',
  'हनुमान जी का जीवन हमें अटूट निष्ठा, निस्वार्थ सेवा और प्रभु के प्रति पूर्ण विश्वास की प्रेरणा देता है।',
  (SELECT id FROM public.categories WHERE slug = 'hanuman' LIMIT 1),
  (SELECT id FROM public.authors WHERE slug = 'editorial-team' LIMIT 1),
  'published',
  '[{"heading":"दास्य भाव और समर्पण की पराकाष्ठा","paragraphs":["श्री हनुमान जी महाराज सनातन धर्म में भक्ति, शक्ति और सेवा के सर्वोच्च प्रतीक हैं। रामायण में अनेक वीर और ज्ञानी हुए, परंतु जो स्थान हनुमान जी को प्राप्त हुआ, वह अद्वितीय है। इसका कारण है उनका ''दास्य भाव'' और प्रभु श्री राम के प्रति अनन्य समर्पण।","हनुमान जी के पास अतुलनीय बल और असीम विद्या थी, परंतु उनका हृदय सदैव एक सेवक के समान विनम्र रहा। उन्होंने अपने बल का कभी अहंकार नहीं किया, बल्कि अपनी हर सफलता का श्रेय प्रभु श्री राम की कृपा को दिया।"],"highlight":"“कवन सो काज कठिन जग माहीं, जो नहिं होई तात तुम्ह पाहीं—विश्वास जब प्रभु पर हो तो असंभव भी संभव हो जाता है।”"},{"heading":"असंभव को संभव करने वाला विश्वास","paragraphs":["जब विशाल समुद्र को लांघने की बात आई, तो जाम्बवंत जी के स्मरण कराने पर हनुमान जी ने तनिक भी संशय नहीं किया। उनके मन में यह दृढ़ विश्वास था कि जब कार्य श्री राम का है, तो शक्ति भी उन्हीं की होगी।","यह प्रसंग हमें सिखाता है कि जीवन में जब भी कोई विकट परिस्थिति या संकट आए, तो भयभीत होने के बजाय ईश्वर पर अटूट विश्वास रखना चाहिए। जब विश्वास सच्चा होता है, तो मनुष्य के भीतर सोई हुई दिव्य शक्तियां जागृत हो जाती हैं।"],"bullets":["निरहंकारिता: अष्टसिद्धि और नवनिधि के स्वामी होकर भी प्रभु के चरणों में दास बनकर रहना।","लक्ष्य के प्रति एकाग्रता: ''राम काज कीन्हे बिनु मोहि कहाँ विश्राम''—कर्तव्य पथ पर बिना रुके आगे बढ़ना।","वाणी का संयम: लंका में विभीषण से भेंट हो या रावण की सभा में संवाद, हर स्थान पर विवेकपूर्ण और संतुलित वाणी।"]},{"heading":"आधुनिक जीवन में हनुमान जी की शिक्षाएं","paragraphs":["आज के युग में जब मनुष्य छोटी-छोटी परेशानियों में विचलित हो जाता है, हनुमान जी का जीवन हमें मानसिक स्थिरता और साहस प्रदान करता है। उनकी भक्ति केवल संकटमोचन की प्रार्थना नहीं, बल्कि अपने जीवन को सेवा, अनुशासन और सत्य के मार्ग पर चलाने का संकल्प है।","जब भी मन कमजोर पड़े, हनुमान जी के चरित्र का स्मरण करें। सच्ची भक्ति मनुष्य को कभी कायर नहीं बनने देती, वह उसे हर चुनौती का सामना करने का आत्मबल देती है।"]}]'::jsonb,
  'गदा',
  '5 मिनट',
  false,
  '2026-03-16T06:00:00+05:30'::timestamptz
)
