VALUES (
  'bhagavad-gita-5-sandesh',
  'श्रीमद्भगवद्गीता के 5 संदेश जो जीवन बदल सकते हैं',
  'गीता के श्लोकों से कर्मयोग, मन के नियंत्रण और जीवन में आंतरिक शांति प्राप्त करने के व्यावहारिक सूत्र।',
  (SELECT id FROM public.categories WHERE slug = 'bhagavad-gita' LIMIT 1),
  (SELECT id FROM public.authors WHERE slug = 'editorial-team' LIMIT 1),
  'published',
  '[{"heading":"गीता: जीवन जीने का व्यावहारिक दर्शन","paragraphs":["श्रीमद्भगवद्गीता केवल कुरुक्षेत्र के मैदान में दिया गया उपदेश नहीं है, बल्कि यह मानव मन के भीतर चलने वाले निरंतर द्वंद्व का स्थायी समाधान है। भगवान श्री कृष्ण ने अर्जुन के विषाद को दूर करते हुए जो ज्ञान दिया, वह आज भी प्रत्येक मनुष्य के लिए उतना ही प्रासंगिक है।"],"highlight":"“कर्मण्येवाधिकारस्ते मा फलेषु कदाचन—कर्म पर तुम्हारा अधिकार है, फल पर नहीं।”"},{"heading":"जीवन के 5 प्रमुख आध्यात्मिक सूत्र","paragraphs":["1. कर्मयोग: फल की चिंता छोड़कर वर्तमान में श्रेष्ठ कर्म करना। जब हम परिणाम से आसक्ति हटा लेते हैं, तो कार्य में एकाग्रता और उत्कृष्टता स्वयं आ जाती है।","2. मन का नियंत्रण: श्री कृष्ण कहते हैं कि मन चंचल है, पर अभ्यास और वैराग्य से इसे वश में किया जा सकता है। अनियंत्रित मन शत्रु है और संयमित मन सच्चा मित्र।","3. समत्व भाव: सुख-दुख, लाभ-हानि और जय-पराजय में मन को स्थिर रखना ही सच्चा योग है।","4. आत्मा की अमरता: देह नश्वर है, पर आत्मा शाश्वत है। इस सत्य को जानकर मृत्यु और भय का निवारण होता है।","5. संपूर्ण शरणागति: सब धर्मों का सार यही है कि अहंकार को त्यागकर उस परम शक्ति की शरण में जाया जाए।"]}]'::jsonb,
  'गीता',
  '6 मिनट',
  false,
  '2026-03-15T06:00:00+05:30'::timestamptz
)
