VALUES (
  'mahadev-bhakti-shiv-naam-mahatva',
  'महादेव की भक्ति और शिव नाम का आध्यात्मिक महत्व',
  'भगवान शिव की साधना, पंचाक्षर मंत्र ''ॐ नमः शिवाय'' का महत्व और ध्यान की गहराई को समझें।',
  (SELECT id FROM public.categories WHERE slug = 'shiv' LIMIT 1),
  (SELECT id FROM public.authors WHERE slug = 'editorial-team' LIMIT 1),
  'published',
  '[{"heading":"भोलेनाथ: सरलता और वैराग्य के देवता","paragraphs":["भगवान शिव को ''आशुतोष'' कहा जाता है, जिसका अर्थ है जो अत्यंत शीघ्र प्रसन्न हो जाते हैं। शिव जी की पूजा में किसी आडंबर की आवश्यकता नहीं होती; केवल एक लोटा शुद्ध जल और बेलपत्र से भी वे रीझ जाते हैं। शिव भक्ति सिखाती है कि ईश्वर को प्रसन्न करने के लिए बाह्य वैभव नहीं, बल्कि हृदय की निर्मलता आवश्यक है।"],"highlight":"“शिव का अर्थ ही है कल्याण—जो हर विष को पीकर भी संसार को अमृत प्रदान करते हैं।”"},{"heading":"पंचाक्षर मंत्र की शक्ति","paragraphs":["''ॐ नमः शिवाय'' पंचाक्षर मंत्र में समस्त सृष्टि के पांच तत्व (पृथ्वी, जल, अग्नि, वायु, आकाश) समाहित हैं। इस मंत्र का निरंतर जप मन को शांत करता है, आंतरिक विकारों को नष्ट करता है और साधक को आत्मसाक्षात्कार की ओर ले जाता है।"]}]'::jsonb,
