-- Article 7/18: vrindavan-jane-se-pehle-baatein
INSERT INTO public.articles (
  slug,
  title,
  description,
  category_id,
  author_id,
  status,
  sections,
  symbol,
  read_time,
  featured,
  published_at
)
VALUES (
  'vrindavan-jane-se-pehle-baatein',
  'वृंदावन जाने से पहले जानने योग्य बातें',
  'वृंदावन धाम दर्शन, प्रमुख मंदिरों के दर्शन का समय और यात्रा के दौरान ध्यान रखने योग्य महत्वपूर्ण बातें।',
  (SELECT id FROM public.categories WHERE slug = 'vrindavan' LIMIT 1),
  (SELECT id FROM public.authors WHERE slug = 'editorial-team' LIMIT 1),
  'published',
  '[{"heading":"धाम यात्रा का आध्यात्मिक दृष्टिकोण","paragraphs":["वृंदावन धाम केवल एक पर्यटन स्थल नहीं, बल्कि भक्ति की पावन भूमि है। यहां प्रत्येक रजकण में श्री राधा-कृष्ण की लीलाएं समाई हुई हैं। वृंदावन जाने का उद्देश्य केवल मंदिरों को देखना नहीं, बल्कि अपने मन को सांसारिक चिंताओं से मुक्त करके धाम के पावन वातावरण में समर्पित करना होना चाहिए।"]}]'::jsonb,
